    "texts": {
      "A": {
        "title": "What to Do for a Burn",
        "text": "If you burn your skin, cool it at once. Hold the burn under cool running water for about twenty minutes. The water takes the heat out of the skin, so the burn stops getting deeper, and it also eases the pain. Water that is cool is best, not freezing cold, because ice can damage the skin even more. Take off rings or tight clothes near the burn before it swells, but do not pull off anything that is stuck to the skin. After cooling, cover the burn loosely with a clean, non-stick cover, such as a piece of cling film. Do not put butter, oil or toothpaste on it, because these can trap heat and cause infection. A large or deep burn, a burn on the face, or any burn on a small child needs a doctor, so call your local emergency number."
      },
      "B": {
        "title": "Why Sunburn Happens",
        "text": "Sunburn is not really a burn from heat. It is damage caused by ultraviolet light, or UV, from the Sun. When UVB rays reach the skin, they harm the DNA inside skin cells. The body notices the damage and sends extra blood and defense cells to the area, which makes the skin red, warm and sore. This is why a sunburn often appears only after several hours, and it is usually at its worst about a day after the time in the Sun. Damaged cells that cannot be repaired die, and that is why burnt skin peels. UV light can pass through clouds, so you can burn on a cloudy day. Repeated sunburn raises the risk of skin cancer later in life, so shade, clothes and sunscreen are important."
      }
    },
